import React, { useState } from "react";

function Home() {

  const [cart, setCart] = useState([]);

  const products = [
    {
      _id: 1,
      name: "Nike Air Max",
      price: 4999,
      image: "https://images.unsplash.com/photo-1542291026-7eec264c27ff"
    },
    {
      _id: 2,
      name: "Oversized T-Shirt",
      price: 1299,
      image: "https://images.unsplash.com/photo-1521572163474-6864f9cf17ab"
    },
    {
      _id: 3,
      name: "Wireless Headphones",
      price: 2999,
      image: "https://images.unsplash.com/photo-1505740420928-5e560c06d30e"
    },
    {
      _id: 4,
      name: "Smart Watch",
      price: 5999,
      image: "https://images.unsplash.com/photo-1517430816045-df4b7de11d1d"
    }
  ];

  const addToCart = (product) => {
    setCart([...cart, product]);
  };

  const totalPrice = cart.reduce(
    (total, item) => total + item.price,
    0
  );

  return (
    <div
      style={{
        background: "#f1f5f9",
        minHeight: "100vh",
        fontFamily: "Arial"
      }}
    >

      {/* Navbar */}

      <div
        style={{
          background: "#0f172a",
          color: "white",
          padding: "18px 40px",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center"
        }}
      >
        <h1>🛒 ShopEasy</h1>

        <div
          style={{
            background: "#2563eb",
            padding: "10px 20px",
            borderRadius: "8px",
            fontWeight: "bold"
          }}
        >
          Cart ({cart.length})
        </div>

      </div>

      {/* Hero */}

      <div
        style={{
          background:
            "linear-gradient(to right,#0f172a,#1e293b)",
          color: "white",
          textAlign: "center",
          padding: "70px 20px"
        }}
      >

        <h1
          style={{
            fontSize: "55px"
          }}
        >
          Welcome To ShopEasy
        </h1>

        <p
          style={{
            marginTop: "20px",
            fontSize: "20px",
            color: "#cbd5e1"
          }}
        >
          Best Deals On Fashion & Electronics
        </p>

      </div>

      {/* Products */}

      <div
        style={{
          padding: "40px"
        }}
      >

        <h2
          style={{
            textAlign: "center",
            marginBottom: "40px",
            fontSize: "40px"
          }}
        >
          Featured Products
        </h2>

        <div
          style={{
            display: "grid",
            gridTemplateColumns:
              "repeat(auto-fit,minmax(250px,1fr))",
            gap: "30px"
          }}
        >

          {products.map((p) => (

            <div
              key={p._id}
              style={{
                background: "white",
                borderRadius: "15px",
                overflow: "hidden",
                boxShadow:
                  "0 4px 12px rgba(0,0,0,0.15)"
              }}
            >

              <img
                src={p.image}
                alt={p.name}
                style={{
                  width: "100%",
                  height: "230px",
                  objectFit: "cover"
                }}
              />

              <div
                style={{
                  padding: "18px"
                }}
              >

                <h2>{p.name}</h2>

                <p
                  style={{
                    color: "green",
                    fontWeight: "bold",
                    fontSize: "20px"
                  }}
                >
                  ₹{p.price}
                </p>

                <button
                  onClick={() => addToCart(p)}
                  style={{
                    width: "100%",
                    padding: "12px",
                    marginTop: "15px",
                    background: "#111827",
                    color: "white",
                    border: "none",
                    borderRadius: "8px",
                    cursor: "pointer",
                    fontSize: "16px"
                  }}
                >
                  Add To Cart
                </button>

              </div>

            </div>

          ))}

        </div>

      </div>

      {/* Cart Section */}

      <div
        style={{
          padding: "40px",
          background: "white",
          margin: "40px",
          borderRadius: "15px",
          boxShadow: "0 4px 10px rgba(0,0,0,0.1)"
        }}
      >

        <h2>🛒 Cart Items</h2>

        {cart.length === 0 ? (
          <p>No items in cart</p>
        ) : (
          cart.map((item, index) => (
            <div
              key={index}
              style={{
                display: "flex",
                justifyContent: "space-between",
                marginTop: "15px",
                paddingBottom: "10px",
                borderBottom: "1px solid #ddd"
              }}
            >
              <span>{item.name}</span>
              <span>₹{item.price}</span>
            </div>
          ))
        )}

        <h3
          style={{
            marginTop: "25px",
            color: "#2563eb"
          }}
        >
          Total: ₹{totalPrice}
        </h3>

      </div>

      {/* Footer */}

      <div
        style={{
          background: "#0f172a",
          color: "white",
          textAlign: "center",
          padding: "25px",
          marginTop: "40px"
        }}
      >
        <p>© 2026 ShopEasy | MERN Stack Project</p>
      </div>

    </div>
  );
}

export default Home;
